#include "navcore/spatial_index.hpp"
#include <cmath>
namespace navcore { namespace { std::string key(int x,int y){return std::to_string(x)+":"+std::to_string(y);} } SpatialIndex::SpatialIndex(const RoadGraph&g,double c):cell_(c){for(const auto&n:g.nodes())for(const auto&e:g.outgoing(n.first)){const auto&a=g.node(e.from),&b=g.node(e.to);int x=static_cast<int>(std::floor((a.latitude+b.latitude)*.5/c)),y=static_cast<int>(std::floor((a.longitude+b.longitude)*.5/c));cells_[key(x,y)].push_back(e);++total_;}} std::vector<Edge> SpatialIndex::query(double lat,double lon,double r,SpatialQueryStats*s)const{auto t=std::chrono::steady_clock::now();std::vector<Edge> out;int d=static_cast<int>(std::ceil(r/(111320*cell_))),x=static_cast<int>(std::floor(lat/cell_)),y=static_cast<int>(std::floor(lon/cell_));for(int i=-d;i<=d;++i)for(int j=-d;j<=d;++j){if(s)++s->queried_cells;auto it=cells_.find(key(x+i,y+j));if(it!=cells_.end())for(const auto&e:it->second){out.push_back(e);if(s)++s->raw_candidates;}}if(s){s->total_indexed_segments=total_;s->filtered_candidates=out.size();s->latency_us=std::chrono::duration<double,std::micro>(std::chrono::steady_clock::now()-t).count();}return out;} RoadGraph make_grid_network(int w,int h){RoadGraph g;for(int y=0;y<h;++y)for(int x=0;x<w;++x)g.add_node({std::to_string(y*w+x),30+y*.001,120+x*.001});for(int y=0;y<h;++y)for(int x=0;x<w;++x){int a=y*w+x;if(x+1<w)g.add_edge({std::to_string(a),std::to_string(a+1),100,50,7.2,"grid",false});if(y+1<h)g.add_edge({std::to_string(a),std::to_string(a+w),100,50,7.2,"grid",false});}return g;} }